$ErrorActionPreference = "Stop"

function Show-Header {
    Clear-Host
    Write-Host "========================================================"
    Write-Host ""
    Write-Host "      CYBER SECURITY DEMONSTRATION"
    Write-Host ""
    Write-Host "========================================================"
    Write-Host ""
}

function Show-Intro {
    Write-Host "This demonstration will:"
    Write-Host ""
    Write-Host "[OK] Collect System Information"
    Write-Host ""
    Write-Host "[OK] Create Desktop Folder"
    Write-Host ""
    Write-Host "[OK] Generate Report.txt"
    Write-Host ""
    Write-Host "Change the current user's wallpaper"
    Write-Host ""
    Write-Host "This demo does not perform persistence, privilege escalation, stealth, or self-propagation."
    Write-Host ""
}

function Show-ProgressLine {
    param(
        [string]$Task,
        [int]$Percent
    )

    $barWidth = 20
    $filled = [Math]::Floor(($Percent / 100) * $barWidth)
    $empty = $barWidth - $filled
    $bar = ("#" * $filled) + ("-" * $empty)

    Write-Host "$Task..."
    Write-Host "[$bar] $Percent%"
    Start-Sleep -Milliseconds 450
    Write-Host "Done"
    Write-Host ""
}

function Get-SystemInfoData {
    $os = Get-CimInstance Win32_OperatingSystem
    $computer = Get-CimInstance Win32_ComputerSystem
    $screen = Add-Type -AssemblyName System.Windows.Forms -PassThru | Out-Null
    $bounds = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds

    [PSCustomObject]@{
        Username = [Environment]::UserName
        ComputerName = [Environment]::MachineName
        WindowsVersion = "$($os.Caption) $($os.Version) (Build $($os.BuildNumber))"
        CPUArchitecture = $computer.SystemType
        ScreenResolution = "$($bounds.Width) x $($bounds.Height)"
        CurrentDate = Get-Date -Format "yyyy-MM-dd"
        CurrentTime = Get-Date -Format "HH:mm:ss"
    }
}

function Write-Report {
    param(
        [string]$Path,
        [object]$Info
    )

    $report = @"
========================
Cyber Security Demo
========================

Username: $($Info.Username)
Computer Name: $($Info.ComputerName)
Windows Version: $($Info.WindowsVersion)
CPU Architecture: $($Info.CPUArchitecture)
Resolution: $($Info.ScreenResolution)
Date: $($Info.CurrentDate)
Time: $($Info.CurrentTime)

========================
End of Report
========================
"@

    Set-Content -Path $Path -Value $report -Encoding UTF8
}

function New-DemoWallpaper {
    param([string]$Path)

    $base64 = @'

'@

    [System.IO.File]::WriteAllBytes($Path, [Convert]::FromBase64String($base64))
}
function Set-Wallpaper {
    param([string]$Path)

    $code = @"
using System;
using System.Runtime.InteropServices;

public static class WallpaperApi {
    [DllImport("user32.dll", SetLastError = true)]
    public static extern bool SystemParametersInfo(int action, int param, string value, int flags);
}
"@

    if (-not ("WallpaperApi" -as [type])) {
        Add-Type $code
    }

    return [WallpaperApi]::SystemParametersInfo(20, 0, $Path, 0x01 -bor 0x02)
}

try {
    Show-Header
    Show-Intro

    $desktop = [Environment]::GetFolderPath("Desktop")
    $demoFolder = Join-Path $desktop "CyberSecurity_Demo"
    $reportPath = Join-Path $demoFolder "Report.txt"
    $wallpaperPath = Join-Path $demoFolder "DemoWallpaper.jpg"
    $originalWallpaper = (Get-ItemProperty "HKCU:\Control Panel\Desktop").WallPaper
    $wallpaperChanged = $false

    Write-Host "Opening this demo runs the following visible local tasks:"
    Write-Host "- Collect basic system information"
    Write-Host "- Create Desktop folder: CyberSecurity_Demo"
    Write-Host "- Generate Report.txt"
    Write-Host "- Create and apply a demo wallpaper"
    Write-Host ""
    Write-Host "Starting transparent demonstration..."
    Write-Host ""

    Show-ProgressLine "[10%] Collecting Username" 10
    Show-ProgressLine "[30%] Reading Windows Version" 30
    $info = Get-SystemInfoData
    Write-Host "[OK] Completed system information collection"
    Write-Host "Username: $($info.Username)"
    Write-Host "Computer Name: $($info.ComputerName)"
    Write-Host "Windows Version: $($info.WindowsVersion)"
    Write-Host "CPU Architecture: $($info.CPUArchitecture)"
    Write-Host "Screen Resolution: $($info.ScreenResolution)"
    Write-Host "Current Date: $($info.CurrentDate)"
    Write-Host "Current Time: $($info.CurrentTime)"
    Write-Host ""

    Show-ProgressLine "[60%] Creating Folder" 60
    New-Item -ItemType Directory -Path $demoFolder -Force | Out-Null
    Write-Host "[OK] Completed folder creation"

    Show-ProgressLine "[90%] Writing Report" 90
    Write-Report -Path $reportPath -Info $info
    Write-Host "[OK] Completed report generation"
    Write-Host "Report saved to: $reportPath"
    Write-Host ""

    Show-ProgressLine "[95%] Preparing Wallpaper" 95
    New-DemoWallpaper -Path $wallpaperPath
    if (Set-Wallpaper -Path $wallpaperPath) {
        $wallpaperChanged = $true
        Write-Host "[OK] Wallpaper changed"
    }
    else {
        Write-Host "[!] Wallpaper could not be changed."
    }

    Show-ProgressLine "[100%] Demo Complete" 100
    Write-Host "[OK] Demo Complete"
    Write-Host ""

    Write-Host "Restore Mode"
    Write-Host "1. Restore Changes"
    Write-Host "2. Exit"

    do {
        $choice = Read-Host "Choose an option"
    } while ($choice -ne "1" -and $choice -ne "2")

    if ($choice -eq "1") {
        if ($wallpaperChanged -and $originalWallpaper) {
            if (Set-Wallpaper -Path $originalWallpaper) {
                Write-Host "[OK] Previous wallpaper restored"
            }
            else {
                Write-Host "[!] Unable to restore the previous wallpaper automatically."
            }
        }

        if (Test-Path $demoFolder) {
            Show-ProgressLine "Removing demo folder" 100
            Remove-Item -Path $demoFolder -Recurse -Force
            Write-Host "[OK] Demo folder removed"
        }
    }

    Write-Host "Exiting. Thank you for reviewing the demonstration."
}
catch {
    Write-Host "[ERROR] $($_.Exception.Message)"
    exit 1
}

